<script setup lang="ts">import { computed } from "vue"import {  type RichTextContent,  type InlineContent,  type InlineText,  type InlineLink,  type InlineMention} from "@/types/blocks"import TextNode from "./nodes/TextNode.vue"import LinkNode from "./nodes/LinkNode.vue"import PageMention from "../PageMention.vue"import { scv, cx } from "css-variants"import { useRC } from "@/composables"/* region Props */export interface TextRendererProps {  content: RichTextContent  rc?: {    root?: string  }}const { content, rc: rcProp } = defineProps<TextRendererProps>()const { rc } = useRC("TextRenderer", rcProp)/* endregion *//* region Styles */const textRendererStyles = scv({  slots: {    root: "whitespace-pre-wrap break-words"  }})const styles = computed(() => {  const resolved = textRendererStyles()  const result: Record<string, string> = {}  for (const [slot, value] of Object.entries(resolved)) {    result[slot] = cx(value, (rc.value as Record<string, string>)[slot])  }  return result as Record<string, string>})/* endregion *//* region Logic */type ComponentIs = string | objectconst getTag = (item: InlineContent): ComponentIs => {  switch (item.type) {    case "text":      return TextNode    case "link":      return LinkNode    case "mention":      return PageMention    default:      return TextNode  }}const getProps = (item: InlineContent): Record<string, any> => {  switch (item.type) {    case "text": {      const textProps = item.props as InlineText["props"]      return {        content: textProps.content      }    }    case "link": {      const linkProps = item.props as InlineLink["props"]      return {        href: linkProps.href,        target: linkProps.target || undefined,        content: linkProps.content      }    }    case "mention": {      const mentionProps = item.props as InlineMention["props"]      return {        pageId: mentionProps.pageId      }    }    default:      return {}  }}/* endregion */defineOptions({  name: "TextRenderer"})</script><template>  <div :class="styles.root">    <template v-for="item in content" :key="item.id">      <component :is="getTag(item)" v-bind="getProps(item)" />    </template>  </div></template>